<script setup>
import {ref,onMounted,computed} from 'vue';import {api} from '../store';const notas=ref([]),error=ref('');const promedio=computed(()=>notas.value.length?(notas.value.reduce((a,n)=>a+n.nota,0)/notas.value.length).toFixed(2):'—');onMounted(async()=>{try{notas.value=await api('/mis-notas')}catch(e){error.value=e.message}});
</script><template><div class="page-heading"><div><div class="eyebrow">SEGUIMIENTO PERSONAL</div><h2>Mis calificaciones</h2><p>Consulta las notas que los docentes vincularon a tu cuenta.</p></div></div><div v-if="error" class="alert alert-danger">{{error}}</div><div class="row g-3 mb-4"><div class="col-md-6"><div class="card metric"><span>Promedio de registros</span><strong>{{promedio}}</strong></div></div><div class="col-md-6"><div class="card metric"><span>Calificaciones</span><strong>{{notas.length}}</strong></div></div></div><div class="card p-4"><div class="table-responsive"><table class="table"><thead><tr><th>Curso</th><th>Docente</th><th>Nota</th><th>Asistencia</th></tr></thead><tbody><tr v-for="n in notas" :key="n.id"><td>{{n.curso}}</td><td>{{n.docente}}</td><td>{{n.nota}}</td><td>{{n.asistencia}}%</td></tr></tbody></table></div><p v-if="!notas.length" class="empty-state">Todavía no tienes calificaciones vinculadas.</p></div></template>